package operators;

public class Arithmeticoperators2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub 
		int num1= 50, num2 = 20 ;
		int add,sub,mul,mod;
		float div;
	    add = num1 + num2;
	    sub = num1 - num2;
	    mul = num1 * num2;
	    mod = num1 % num2;
	    div = num1 / num2;
	    
	    System.out.println("Add = "+add+"\nSub= "+sub+"\nMul= "+mul+"\nDiv= "+div+"\nMod ="+mod);
	}

}
